import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"跨位面倫理準則","description":"","frontmatter":{},"headers":[],"relativePath":"ja/88-跨位面伦理准则.md","filePath":"ja/88-跨位面伦理准则.md","lastUpdated":1789183869000}'),l={name:"ja/88-跨位面伦理准则.md"};function i(h,t,o,n,p,s){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="跨位面倫理準則" tabindex="-1">跨位面倫理準則 <a class="header-anchor" href="#跨位面倫理準則" aria-label="Permalink to &quot;跨位面倫理準則&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>88</td></tr><tr><td>所属モジュール</td><td>跨位面インタラクションと時間ルール</td></tr><tr><td>コアキーワード</td><td>跨位面倫理、文明自主、不干渉、文化尊重、共生外交</td></tr></tbody></table><h2 id="第一節-倫理準則の哲学的基礎" tabindex="-1">第一節 倫理準則の哲学的基礎 <a class="header-anchor" href="#第一節-倫理準則の哲学的基礎" aria-label="Permalink to &quot;第一節 倫理準則の哲学的基礎&quot;">​</a></h2><p>跨位面倫理準則は、アンカー共生文明が他の位面文明とインタラクションを行う際に遵守しなければならない道徳規範と行動準則である。その哲学的基礎は「文明主体性」原則——それぞれの位面の文明は、その発展水準の高低、人種形態、社会制度を問わず、剥奪不可能な主体性と自主発展権を有する——である。いかなる外来文明も、いかなる理由をもってこの主体性を剥奪し、あるいは自らの意志を他の文明に押し付けてはならない。</p><p>この哲学的基礎の確立は、アンカー共生文明の「反略奪」核心理念と一脈相承するものである。略奪式文明の本質的特徴は、他の文明の主体性を認めず、他の文明を利用可能な資源あるいは征服可能な対象と見なすことである。アンカー共生文明が略奪式文明を真に超越するためには、跨位面インタラクションにおいてこのような心态を徹底的に捨て去り、出会うすべての文明に対して平等、尊重、共生の態度で接さなければならない。</p><p>跨位面倫理準則の効力範囲は、位面穿梭、跨位面通信、考古活動、貿易往来、文化交流、技術協力、緊急事態における人道的干渉を含むがこれらに限定されない、すべての跨位面インタラクション行為をカバーする。いかなる組織と個人も、跨位面インタラクションを行う際には、本準則の各項規定を遵守しなければならない。</p><h2 id="第二節-六大倫理原則" tabindex="-1">第二節 六大倫理原則 <a class="header-anchor" href="#第二節-六大倫理原則" aria-label="Permalink to &quot;第二節 六大倫理原則&quot;">​</a></h2><p>跨位面倫理準則は六大基本原則から構成され、完全な倫理価値体系を形成している:</p><table tabindex="0"><thead><tr><th>原則</th><th>核心内包</th><th>具体的要求</th></tr></thead><tbody><tr><td>文明自主原則</td><td>目標位面文明の自主発展権を尊重し、その内部事務に強行干渉しない</td><td>目標文明の社会制度、イデオロギー、発展道路を強制的に変更してはならない；目標文明内部に代理人や傀儡政権を培植してはならない</td></tr><tr><td>不干渉原則</td><td>目標文明が絶滅級危機に直面し、かつ積極的に援助を請求した場合を除き、いかなる実質的干渉も行わない</td><td>目標文明の内部紛争に介入してはならない；目標文明のいかなる一方にも武器や軍事援助を提供してはならない；目標文明の世論と政治プロセスを操作してはならない</td></tr><tr><td>文化尊重原則</td><td>目標文明の文化伝統、宗教信仰、風俗習慣を尊重する</td><td>目標文明の文化に対して差別的評価や悪意のある嘲笑を行ってはならない；本位面の文化製品と価値観を強制的に推進してはならない；「開化」を名として文化同化を行ってはならない</td></tr><tr><td>平等互利原則</td><td>跨位面交往は平等の基礎に築かれなければならず、双方が交往から利益を得られることを確保する</td><td>技術優位を利用して不平等貿易を行ってはならない；目標文明の資源を略奪してはならない；技術輸出は目標文明の受容能力と社会的影響を考慮しなければならない</td></tr><tr><td>最小影響原則</td><td>跨位面インタラクションは目標文明に対する外部影響を可能な限り減少させるべきである</td><td>低接触、低干渉のインタラクション方式を優先採用する；インタラクション活動の範囲と強度は必要限度内に厳格に制御する；インタラクション終了後は不必要な残留影響を評価し除去する</td></tr><tr><td>可問責原則</td><td>すべての跨位面インタラクション行為は追跡可能、監督可能、問責可能でなければならない</td><td>完全なインタラクション档案とログを構築する；独立した倫理監督機構を設立する；倫理準則に違反する行為を調査し処罰する</td></tr></tbody></table><p>六大原則の間には内在的な論理的関連が存在する: 文明自主原則は根本価値であり、不干渉原則は核心要求であり、文化尊重原則は文化層面の体現であり、平等互利原則は経済層面の保障であり、最小影響原則は操作層面の規範であり、可問責原則は制度層面の制約である。六者は共同で「価値—要求—体現—保障—規範—制約」の完全な倫理閉ループを構成している。</p><h2 id="第三節-異なるインタラクションシーンの倫理規範" tabindex="-1">第三節 異なるインタラクションシーンの倫理規範 <a class="header-anchor" href="#第三節-異なるインタラクションシーンの倫理規範" aria-label="Permalink to &quot;第三節 異なるインタラクションシーンの倫理規範&quot;">​</a></h2><h3 id="_3-1-考古シーンの倫理規範" tabindex="-1">3.1 考古シーンの倫理規範 <a class="header-anchor" href="#_3-1-考古シーンの倫理規範" aria-label="Permalink to &quot;3.1 考古シーンの倫理規範&quot;">​</a></h3><p>跨位面考古は最も一般的なインタラクションシーンの一つであり、その倫理規範の核心は「邪魔をしない」ことである。考古チームは複製鏡+隔離空間+僅回伝知識の標準方案を厳格に遵守し、考古プロセスが目標文明に感知されないことを確保しなければならない。なお生きた文明が存在する位面については、考古範囲はすでに廃棄された遺跡区域に厳格に限定されなければならず、生きた文明の居住区に対していかなる形式のスキャンや複製も行ってはならない。</p><p>考古発見の知識を回伝し発表する際には、目標文明の文化的敏感性を尊重しなければならない。考古発見が目標文明の宗教聖物、祖先遺骸、あるいは文化タブーに関わる場合、関連情報は発表前に跨位面倫理委員会の文化的敏感性審査を経なければならず、必要に応じて敏感な詳細に対して曖昧化処理を行う。</p><h3 id="_3-2-通信シーンの倫理規範" tabindex="-1">3.2 通信シーンの倫理規範 <a class="header-anchor" href="#_3-2-通信シーンの倫理規範" aria-label="Permalink to &quot;3.2 通信シーンの倫理規範&quot;">​</a></h3><p>跨位面通信は目標文明と直接交流を行う方式であり、その倫理規範の核心は「誠実と尊重」である。通信内容は真実でなければならず、意図的に虚偽情報を提供したり欺瞞的宣伝を行ったりしてはならない；通信の語気は平等でなければならず、発展水準の低い文明に対して高慢な態度をとってはならない；通信テーマは目標文明の同意を経なければならず、本位面のイデオロギーや宗教信仰を強制的にプッシュしてはならない。</p><p>初めて未知の文明と通信を確立する際には、「漸進式接触」規範を遵守しなければならない: まず中性的な数学と物理の信号を送信して相手の知能水準とコミュニケーション能力を確認し、その後相手の応答に基づいて徐々に交流範囲を拡大し、初回接触時に複雑な文化や技術情報を送信してはならない。</p><h3 id="_3-3-貿易シーンの倫理規範" tabindex="-1">3.3 貿易シーンの倫理規範 <a class="header-anchor" href="#_3-3-貿易シーンの倫理規範" aria-label="Permalink to &quot;3.3 貿易シーンの倫理規範&quot;">​</a></h3><p>跨位面貿易の倫理規範の核心は「公平と持続可能」である。貿易は双方の自発的な基礎に築かれなければならず、情報の非対称性や技術優位を利用して強迫的取引を行ってはならない；貿易価格は公正でなければならず、略奪的価格設定を行ってはならない；貿易商品には目標文明に社会的衝撃や生態破壊をもたらす可能性のある内容が含まれてはならない。</p><p>特に注意すべきは、修練技術と高エネルギー武器の跨位面貿易は最も厳格な倫理制限を受けることである。発展水準の低い文明に高段修練技術を輸出することは、その社会構造の不均衡と内部紛争の激化を引き起こす可能性がある；武器を輸出することは直接戦争を引き起こす可能性がある。したがって、この二類の貿易は原則として禁止されており、極めて特殊な状況においてのみアンカー議事会全体会議の審査批准を経て行うことができる。</p><h3 id="_3-4-緊急干渉シーンの倫理規範" tabindex="-1">3.4 緊急干渉シーンの倫理規範 <a class="header-anchor" href="#_3-4-緊急干渉シーンの倫理規範" aria-label="Permalink to &quot;3.4 緊急干渉シーンの倫理規範&quot;">​</a></h3><p>目標位面文明が絶滅級危機（小惑星衝突、スーパーペスト、法則崩壊など）に直面した場合、アンカー共生文明は人道的干渉を行うことができる。しかし、このような緊急事態においても、以下の倫理規範を遵守しなければならない:</p><ul><li>干渉前には可能な限り目標文明のインフォームドコンセントを取得し、目標文明が危機により有効な応答を行えない場合は、跨位面倫理委員会が代理で「推定同意」判断を行う</li><li>干渉手段は目標文明に対する影響が最小の方案を選択し、直接干渉（直接降臨して救援するなど）よりも間接干渉（小惑星の軌道を変えるなど）を優先する</li><li>干渉過程において目標文明の資源や技術を取得する機会を利用してはならない</li><li>干渉終了後は直ちに撤収し、目標位面に恒久的な存在を残してはならない</li><li>事後に跨位面倫理委員会に完全な干渉報告を提出し、倫理審査を受ける</li></ul><h2 id="第四節-倫理監督と違反処理" tabindex="-1">第四節 倫理監督と違反処理 <a class="header-anchor" href="#第四節-倫理監督と違反処理" aria-label="Permalink to &quot;第四節 倫理監督と違反処理&quot;">​</a></h2><p>衡元宙は独立した倫理監督機構として「跨位面倫理委員会」を設立し、跨位面倫理準則の制定と解釈、高リスク跨位面インタラクションプロジェクトの審査批准、倫理違反訴状の受理、違反行為に対する調査と裁決を担当する。委員会は異なる人種、異なる専門的背景の倫理学者、法学者、科学者、文明代表から構成され、決定の多元性と公正性を確保する。</p><p>跨位面倫理準則に違反する行為に対しては、情状の軽重に応じて、口頭警告、書面譴責、跨位面インタラクション資格の停止、穿梭許可の取り消し、罰金、懲役刑、極端な場合の「位面追放」（衡元宙主要位面における居住権の剥奪）を含む処理措置が講じられる。すべての倫理違反処理結果は個人または組織の倫理档案に記録され、永久に保存される。</p><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>跨位面倫理準則はアンカー共生文明の道徳的高さの集中的体現である。それは「何をしてはならないか」を規定するだけでなく、より重要なのは「何になるべきか」を昭示している——真に偉大な文明とは、どれだけ多くの他の文明を征服したかではなく、どれだけ多くの他の文明の主体性を尊重したかである。衡元宙が星際共生への道を歩む上で、跨位面倫理準則は常に方向を導く道徳的灯台となるであろう。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>81-位面穿梭規則</li><li>87-僅回伝知識原則</li><li>04-反略奪主義核心論綱</li></ul>',30)])])}const b=a(l,[["render",i]]);export{c as __pageData,b as default};
